const search=document.getElementById('course-search');const list=document.getElementById('course-list');function render(){const q=search.value.toLowerCase().trim();const matches=courses.filter(c=>(c.name+' '+(c.location||'')+' '+(c.designer||'')+' '+c.difficulty).toLowerCase().includes(q));const fragment=document.createDocumentFragment();for(const c of matches){const li=document.createElement('li');const name=document.createElement('strong');name.textContent=c.name;const difficulty=document.createElement('span');difficulty.textContent=[c.location, 'Difficulty: '+(c.difficulty??'Unlisted'), c.designer?('Designer: '+c.designer):null].filter(Boolean).join(' · ');li.append(name,difficulty);fragment.append(li);}list.replaceChildren(fragment);document.getElementById('course-count').textContent=matches.length.toLocaleString()+' of '+courses.length.toLocaleString()+' courses';if(!matches.length){const li=document.createElement('li');li.textContent='No courses match your search.';list.append(li);}}search.addEventListener('input',render);render();